        (None, true) => Source::Default,
        (None, false) => Source::Flag("--tag".to_string()),
        (Some(path), true) => Source::File(path.to_path_buf()),
        (Some(path), false) => {
            Source::Flag(format!("{} and --tag", run_config::display_path(path)))
