            } else {
                tags.join(", ")
            },
            "none",
            tags_src,
        ),
    ];
    println!("Config:");
    println!("  files             {}", config_summary(&config_files));
    for line in run_config::lines(&params) {
        println!("{line}");
    }
    println!();

