    // children get the resolved knobs and the record sink, and this process holds the sleep
    // inhibit and the clock pin for all of them.
    let exe = match std::env::current_exe() {
        Ok(p) => p,
        Err(e) => {
            eprintln!("error: current_exe: {e}");
            std::process::exit(1);
        }
    };
