        ),
        Param::new(
            "inhibit",
            if inhibit { "on" } else { "off" }.to_string(),
            "on",
            inhibit_src,
        ),
        Param::new(
            "verbose",
            if verbose { "on" } else { "off" }.to_string(),
            "off",
