        scratch: scratch.path(),
        runs,
        run_sleep_s,
        verbose,
        decimals: decimals as usize,
        trim_runs,
    });
    for (name, _) in &runners {
        if let Err(e) = runner.bench(name, &cfg, &record_spec) {
            eprintln!("error: {e}");
            drop(scratch);
            drop(freq_pin);
            std::process::exit(1);
        }
    }
}

