120	    {
121	        let mut text = String::new();
122	        for line in section {
123	            text.push_str(line);
124	            text.push('\n');
125	        }
126	        return Ok(Some(text));
127	    }
128	    let Some(value) = old.and_then(|t| t.get(name)) else {
129	        return Ok(None);
130	    };
131	    let mut table = toml::Table::new();
132	    table.insert(name.to_string(), value.clone());
133	    match toml::to_string(&table) {
134	        Ok(text) => Ok(Some(text)),
135	        Err(e) => Err(format!("[{name}] will not write back as TOML: {e}")),
136	    }
137	}
