/// series and no pick is refused with each listed, since an experiment's file holds many and a
/// guess would start from the wrong one.
fn chosen<'a>(
    runs: &'a [crate::record::RecordedRun],
    series: Option<&str>,
) -> Result<&'a crate::record::RecordedRun, String> {
