1	//! `analyze`: whether a claim held, read back from records across invocations.
2	//!
3	//! Every number a run prints is a claim about that invocation alone, and only repetition shows
4	//! whether it holds. This module reads records back and makes the claim across invocations, on
5	//! [`crate::record`]'s struct and [`crate::series`]'s arithmetic, so no second copy of either
6	//! exists.
7	//!
8	//! - **Three units.** A run is one record. An invocation is a series' runs of one bench, with a
9	//!   trimmed mean and the `LSC trimmed` it claims. A group is the invocations that share a bench,
10	//!   a host, and the value of every `--by` tag.
11	//! - **A group against itself** is the first report: how far its invocations' trimmed means
12	//!   spread, against what each claimed, and so what change the group could really detect.
13	//! - **Session order** is series order, since a series id starts with its UTC start.
14	
15	use std::collections::BTreeMap;
16	use std::path::PathBuf;
17	
18	use crate::record::{self, AnalyzedRun, Skipped};
19	use crate::series::{Series, Trim, Trimmed, t975};
20	
21	/// One invocation of one bench: its runs' means in run order and what they claim.
22	#[derive(Debug, Clone)]
23	struct Invocation {
24	    series: String,
25	    bench: String,
26	    host: String,
27	    tags: BTreeMap<String, String>,
28	    /// Run means, ns, in run order.
29	    means: Vec<f64>,
30	    /// Each run's mean delivered clock, GHz, for the runs that read one.
31	    ghz: Vec<f64>,
32	    /// Each run's block-mean lag-1 autocorrelation, for the runs that have one.
33	    lag1: Vec<f64>,
34	}
35	
36	impl Invocation {
37	    /// The trimmed pair, `None` when the invocation is too short to trim.
38	    fn trimmed(&self, trim: Trim) -> Option<Trimmed> {
39	        Trimmed::of(&self.means, trim)
40	    }
41	}
42	
43	/// Every record under `paths`, a directory being its `*.jsonl` in name order, with what was
44	/// skipped and how many files were read.
45	fn collect(paths: &[PathBuf]) -> Result<(Vec<AnalyzedRun>, Skipped, usize), String> {
46	    let mut files = Vec::new();
47	    for path in paths {
48	        if path.is_dir() {
49	            let listing = std::fs::read_dir(path)
50	                .map_err(|e| format!("reading {}: {e}", path.display()))?;
51	            let mut found: Vec<PathBuf> = listing
52	                .filter_map(|entry| entry.ok().map(|e| e.path()))
53	                .filter(|p| p.extension().is_some_and(|x| x == "jsonl"))
54	                .collect();
55	            found.sort();
56	            files.extend(found);
57	        } else {
58	            files.push(path.clone());
59	        }
60	    }
61	    let mut skipped = Skipped::default();
62	    let mut runs = Vec::new();
63	    for file in &files {
64	        runs.extend(record::read_analyzed(file, &mut skipped)?);
65	    }
66	    Ok((runs, skipped, files.len()))
67	}
68	
69	/// The runs gathered into invocations, a series' runs of one bench each, in run order, and the
70	/// invocations in session order.
71	fn invocations(runs: Vec<AnalyzedRun>) -> Vec<Invocation> {
72	    let mut by_key: BTreeMap<(String, String), Vec<AnalyzedRun>> = BTreeMap::new();
73	    for run in runs {
74	        by_key
75	            .entry((run.series.clone(), run.bench.clone()))
76	            .or_default()
77	            .push(run);
78	    }
79	    by_key
80	        .into_values()
81	        .map(|mut runs| {
82	            runs.sort_by_key(|r| r.run);
83	            let first = &runs[0];
84	            Invocation {
85	                series: first.series.clone(),
86	                bench: first.bench.clone(),
87	                host: first.host.clone(),
88	                tags: first.tags.clone(),
89	                means: runs.iter().map(|r| r.mean_ns).collect(),
90	                ghz: runs
91	                    .iter()
92	                    .filter(|r| !r.clock_khz.is_empty())
93	                    .map(|r| r.clock_khz.iter().sum::<u64>() as f64 / r.clock_khz.len() as f64 / 1e6)
94	                    .collect(),
95	                lag1: runs.iter().filter_map(|r| lag1(&r.block_mean_ns)).collect(),
96	            }
97	        })
98	        .collect()
99	}
100	
101	/// The lag-1 autocorrelation of a series, `None` below two points or with no spread.
102	fn lag1(xs: &[f64]) -> Option<f64> {
103	    if xs.len() < 2 {
104	        return None;
105	    }
106	    let mean = xs.iter().sum::<f64>() / xs.len() as f64;
107	    let den: f64 = xs.iter().map(|x| (x - mean) * (x - mean)).sum();
108	    if den == 0.0 {
109	        return None;
110	    }
111	    let num: f64 = xs.windows(2).map(|w| (w[0] - mean) * (w[1] - mean)).sum();
112	    Some(num / den)
113	}
114	
115	/// A group's key: its bench, its host, and its value of each `--by` tag, `-` when a record
116	/// lacks the tag.
117	type Key = (String, String, Vec<String>);
118	
119	/// The invocations grouped by bench, host, and each tag in `by`, the groups in key order.
120	fn groups(invs: Vec<Invocation>, by: &[String]) -> Vec<(Key, Vec<Invocation>)> {
121	    let mut out: BTreeMap<Key, Vec<Invocation>> = BTreeMap::new();
122	    for inv in invs {
123	        let values = by
124	            .iter()
125	            .map(|tag| match inv.tags.get(tag) {
126	                Some(v) => v.clone(),
127	                None => "-".to_string(),
128	            })
129	            .collect();
130	        out.entry((inv.bench.clone(), inv.host.clone(), values))
131	            .or_default()
132	            .push(inv);
133	    }
134	    out.into_iter().collect()
135	}
136	
137	/// A group against itself: the invocations' trimmed means and what they say together.
138	#[derive(Debug, Clone, PartialEq)]
139	struct Qualified {
140	    /// Invocations trimmed, the ones every other number is over.
141	    inv: usize,
142	    /// Invocations too short to trim, left out.
143	    untrimmed: usize,
144	    /// The mean of the invocations' trimmed means, ns.
145	    grand: f64,
146	    /// The invocations' trimmed means, in session order.
147	    trimmed: Vec<f64>,
148	    /// Their sample stdev as a percent of `grand`, `None` below two.
149	    sd_pct: Option<f64>,
150	    /// Their range as a percent of `grand`.
151	    range_pct: f64,
152	    /// The mean claimed `LSC trimmed` as a percent of `grand`.
153	    lsc_pct: f64,
154	    /// Pairs of invocations further apart than their claim, and the pairs.
155	    exceed: (usize, usize),
156	    /// The mean stdev of an invocation's run means as a percent of `grand`.
157	    run_sd_pct: Option<f64>,
158	    /// The mean delivered clock over every run, GHz.
159	    ghz: Option<f64>,
160	    /// The mean block lag-1 over every run.
161	    lag1: Option<f64>,
162	    /// The smallest change one invocation against one would call real, from the spread between
163	    /// invocations, as a percent of `grand`, `None` below two.
164	    detect_pct: Option<f64>,
165	    /// The fitted change over the session, first invocation to last, as a percent of `grand`,
166	    /// `None` below three.
167	    trend_pct: Option<f64>,
168	}
169	
170	/// The mean of a slice, `None` when it is empty.
171	fn mean(xs: &[f64]) -> Option<f64> {
172	    (!xs.is_empty()).then(|| xs.iter().sum::<f64>() / xs.len() as f64)
173	}
174	
175	/// Qualify a group against itself under `trim`. `None` when no invocation could be trimmed.
176	fn qualify(invs: &[Invocation], trim: Trim) -> Option<Qualified> {
177	    let pairs: Vec<(&Invocation, Trimmed)> = invs
178	        .iter()
179	        .filter_map(|inv| inv.trimmed(trim).map(|t| (inv, t)))
180	        .collect();
181	    let k = pairs.len();
182	    let grand = mean(&pairs.iter().map(|(_, t)| t.mean).collect::<Vec<_>>())?;
183	    let trimmed: Vec<f64> = pairs.iter().map(|(_, t)| t.mean).collect();
184	    let lscs: Vec<f64> = pairs.iter().map(|(_, t)| t.lsc()).collect();
185	    let pct = |v: f64| 100.0 * v / grand;
186	    let spread = Series::of(&trimmed);
187	    let mut exceed = (0, 0);
188	    for i in 0..k {
189	        for j in i + 1..k {
190	            exceed.1 += 1;
191	            let claim = ((lscs[i] * lscs[i] + lscs[j] * lscs[j]) / 2.0).sqrt();

