/// The `analyze` command: read `paths`, group by bench, host, and each key in `by`, and print
/// each group against itself under `trim`, or, with `sides`, the sides compared. Returns the
/// exit code.
pub fn run(paths: &[PathBuf], by: &[String], sides: Option<&Sides>, trim: Trim) -> i32 {
    if paths.is_empty() {
        eprintln!("error: analyze: name the record files or directories to read");
        return 2;
    }
    let (runs, skipped, files) = match collect(paths) {
        Ok(read) => read,
        Err(e) => {
            eprintln!("error: analyze: {e}");
            return 1;
        }
    };
    let n_runs = runs.len();
    let invs = invocations(runs);
    let n_invs = invs.len();
    let many_hosts = invs.iter().any(|i| i.host != invs[0].host);
    let mut dims = vec!["bench".to_string(), "host".to_string()];
    dims.extend(
        by.iter()
            .filter(|d| !dims.contains(d))
            .cloned()
            .collect::<Vec<_>>(),
    );
    if let Some(sides) = sides {
        dims.retain(|d| *d != sides.key);
    }
    // Sides not named are every value the records hold, in the order each first ran, so a
    // ladder recorded as `a b c` compares a, then b, then c.
    let named;
    let sides = match sides {
        Some(s) if s.values.is_empty() => {
            let values = values_in_order(&invs, &s.key);
            if values.len() < 2 {
                eprintln!(
                    "error: analyze: --compare: the records hold {} value{} of {}, {}, and a \
                     comparison needs two",
                    values.len(),
                    if values.len() == 1 { "" } else { "s" },
                    s.key,
                    values.join(", ")
                );
                return 2;
            }
            named = Sides {
                key: s.key.clone(),
                values,
            };
            Some(&named)
        }
        other => other,
    };
    let groups = groups(invs, &dims);
    println!(
        "{n_runs} runs in {files} file{}, {n_invs} invocations, {} groups, trim {trim}",
        if files == 1 { "" } else { "s" },
        groups.len()
    );
    if skipped.unreadable > 0 || skipped.no_series > 0 {
        println!(
            "skipped: {} unreadable lines, {} records with no series",
            skipped.unreadable, skipped.no_series
        );
    }
    let text = match sides {
        None => report(&groups, &dims, many_hosts, trim),
        Some(sides) => comparison(&groups, &dims, many_hosts, sides, trim),
    };
    print!("{text}");
    0
}

